        self.stream = deque(maxlen=self.max_len)

    def query(self, letter: str) -> bool:
        self.stream.append(letter)
        node = self.root
        for ch in reversed(self.stream):
            node = node.children.get(ch)
            if node is None:
                return False
            if node.is_end:
                return True
        return False

